#!/usr/bin/env python3
"""Emit web/js/registry_data.js from config/registry.json (single source of truth; no tickers hard-coded in UI)."""
import json,sys
d=json.load(open('config/registry.json'))
fam={k:{'enabled':v['enabled'],'anchor':v['anchor']['id'],'books':[b['id'] for b in v['books']],
        'unresolved':[b['id'] for b in v['books'] if not d['symbol_master'].get(b['id'],{}).get('multiplier')],'notes':{b['id']:b.get('needs_verification') or b.get('assumed') for b in v['books'] if b.get('needs_verification') or b.get('assumed')}} for k,v in d['families'].items()}
out={'futures':[t for t in d['futures_tickers'] if fam[t]['enabled']],'standard':d['standard_tickers'],'display':d['display'],'aliases':d['aliases'],'volatility':d.get('volatility_tickers',[]),'vol_links':d.get('vol_links',{}),'families':fam,'weighting':d['weighting']}
open('web/js/registry_data.js','w').write('// GENERATED by tools/gen_registry_js.py from config/registry.json. Do not edit.\nwindow.VT_REGISTRY='+json.dumps(out,indent=1)+';\n')
